def backfill_partner_sent(apps, schema_editor):
    """Phiếu đối tác đã thấy/đã làm (đã nhận, đã báo SL, hoặc không còn nháp) → coi như đã gửi."""
    Order = apps.get_model('san_xuat', 'SxSubcontractOrder')
    qs = (
        Order.objects.filter(partner__isnull=False, partner_sent_at__isnull=True)
        .exclude(status='cancelled')
        .filter(
            Q(partner_accepted_at__isnull=False)
            | Q(output_reports__isnull=False)
            | ~Q(status='draft')
        )
        .distinct()
    )
    for order in qs:
        order.partner_sent_at = order.partner_accepted_at or order.sent_at or order.created_at
        order.save(update_fields=['partner_sent_at'])


